package dev.umbral.test;
import dev.umbral.UmbralContent;
import dev.umbral.access.*;
import dev.umbral.airlock.*;
import dev.umbral.airlock.AirlockProtocol.*;
import dev.umbral.block.*;
import dev.umbral.filter.*;
import dev.umbral.network.NetworkService;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.world.phys.Vec3;
import java.util.*;

public final class AirlockGameTests {
    static final String S="umbral-test:network";static final BlockPos OUT=new BlockPos(5,1,2);
    record Setup(FilterGameTests.Setup base,DeviceBlockEntity outer){}
    Setup setup(GameTestHelper t){var f=new FilterGameTests();var b=f.setup(t);var o=f.put(t,OUT,UmbralContent.DOOR,b.owner());t.setBlock(OUT.above(),UmbralContent.DOOR.defaultBlockState().setValue(SecurityDoorBlock.HALF,DoubleBlockHalf.UPPER));o.bind(b.owner().getUUID(),b.core());b.owner().setPos(Vec3.atCenterOf(b.filter().getBlockPos()).add(-1,0,0));return new Setup(b,o);}
    String configure(Setup i,int width){return AirlockService.configure(i.base.owner(),i.base.filter(),i.outer.asDoorTarget(),i.base.door().asDoorTarget(),width);}
    void enable(GameTestHelper t,Setup i){t.assertTrue(configure(i,3).equals("airlock_saved"),"Aligned doors saved");t.assertTrue(AirlockService.enable(i.base.filter(),true).equals("airlock_enabled"),"Complete online airlock enables");}
    Request request(Setup i,Operation op){var b=i.base;return new Request(b.filter().getBlockPos(),b.filter().identity(),b.filter().link(),b.filter().getBlockPos(),b.filter().identity(),5,b.filter().filter().revision(),op,i.outer.asDoorTarget(),b.door().asDoorTarget(),3);}
    ServerPlayer visitor(GameTestHelper t,Setup i){var p=t.makeMockServerPlayerInLevel();p.setPos(Vec3.atLowerCornerOf(i.outer.getBlockPos()).add(.5,0,-1.5));var grant=AccessRegistry.get(t.getLevel()).issue(i.base.owner().getUUID(),i.base.core().link(),"Visitante");var card=new ItemStack(UmbralContent.ACCESS_CARD);card.set(UmbralContent.CARD_ID,grant.id());p.getInventory().setItem(0,card);return p;}
    void finish(GameTestHelper t,ServerPlayer... p){for(var v:p)t.getLevel().getServer().getPlayerList().remove(v);t.succeed();}
    void start(GameTestHelper t,Setup i,ServerPlayer p){t.assertTrue(AirlockService.card(p,i.outer,p.getInventory().getItem(0).get(UmbralContent.CARD_ID))==AccessService.Result.AIRLOCK_QUEUED,"Valid subject starts admission");}
    void inside(Setup i,ServerPlayer p){p.setPos(Vec3.atLowerCornerOf(i.base.filter().getBlockPos().east()).add(.5,0,.5));}
    @GameTest(structure=S) public void configurationReusesTwoDoorsAndAutoChamber(GameTestHelper t){var i=setup(t);enable(t,i);t.assertTrue(i.outer.airlockLink().outer()&&!i.base.door().airlockLink().outer(),"Both persistent interlocks stored");t.assertTrue(i.base.filter().filter().mode()==FilterState.Mode.ACCESS&&i.base.filter().filter().armed(),"Inspector activated atomically");t.assertTrue(AirlockService.chamber(i.base.filter()).getXsize()==3,"Width creates chamber without redrawing");t.succeed();}
    @GameTest(structure=S,maxTicks=80) public void guardRejectsEveryOpeningPathUntilOtherDoorFullyCloses(GameTestHelper t){var i=setup(t);enable(t,i);i.base.filter().airlock().enabled(false);t.assertTrue(SecurityDoorBlock.open(t.getLevel(),i.outer),"First door opens");t.assertFalse(SecurityDoorBlock.open(t.getLevel(),i.base.door()),"Other open target rejected");t.runAfterDelay(15,()->{SecurityDoorBlock.closeIfClear(t.getLevel(),i.outer);t.assertFalse(SecurityDoorBlock.open(t.getLevel(),i.base.door()),"Closing motion also interlocks");t.runAfterDelay(18,()->{t.assertTrue(SecurityDoorBlock.open(t.getLevel(),i.base.door()),"Other door opens only after fully closed");t.succeed();});});}
    @GameTest(structure=S) public void activeAirlockRejectsPolicyDowngradeAndUnlink(GameTestHelper t){var i=setup(t);enable(t,i);t.assertTrue(FilterService.arm(i.base.filter(),false).equals("airlock_active"),"No disarm bypass");t.assertTrue(FilterService.mode(i.base.filter(),FilterState.Mode.INFORM).equals("airlock_active"),"No mode bypass");t.assertTrue(FilterService.unlink(i.base.filter()).equals("airlock_active"),"No unlink bypass");t.succeed();}
    @GameTest(structure=S) public void misalignedOrSameDoorConfigurationIsRejectedAtomically(GameTestHelper t){var i=setup(t);var r=AirlockService.configure(i.base.owner(),i.base.filter(),i.base.door().asDoorTarget(),i.base.door().asDoorTarget(),3);t.assertTrue(r.equals("airlock_doors"),"Same door rejected");t.assertTrue(i.base.filter().airlock().outer()==null&&i.outer.airlockLink()==null,"No partial mutation");t.succeed();}
    @GameTest(structure=S) public void foreignOwnerAndOldRevisionCannotConfigure(GameTestHelper t){var i=setup(t);var request=request(i,Operation.SAVE);t.assertFalse(AirlockProtocol.handle(i.base.visitor(),request).valid(),"Foreign console rejected");i.base.filter().filter().rule("minecraft:lava_bucket",1);t.assertTrue(AirlockProtocol.handle(i.base.owner(),request).result().equals("stale"),"Stale layout rejected");t.succeed();}
    @GameTest(structure=S) public void enablingNeedsRulesAndClosedDoors(GameTestHelper t){var i=setup(t);configure(i,3);SecurityDoorBlock.open(t.getLevel(),i.outer);t.assertTrue(AirlockService.enable(i.base.filter(),true).equals("airlock_close_doors"),"Open door prevents enable");t.assertTrue(i.base.door().airlockLink()==null,"No partial interlock");t.succeed();}
    @GameTest(structure=S) public void disablingRemovesBothInterlocksButRetainsInspectionPolicy(GameTestHelper t){var i=setup(t);enable(t,i);t.assertTrue(AirlockService.enable(i.base.filter(),false).equals("airlock_disabled"),"Disable succeeds");t.assertTrue(i.outer.airlockLink()==null&&i.base.door().airlockLink()==null,"Both doors released");t.assertTrue(i.base.door().filterGuard()!=null,"FILTRO remains explicit separate policy");t.succeed();}
    @GameTest(structure=S,maxTicks=120) public void clearVisitorWaitsForClosureAndFreshInspection(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);start(t,i,p);t.runAfterDelay(15,()->{inside(i,p);t.runAfterDelay(35,()->{t.assertTrue(AirlockService.closed(t.getLevel(),i.outer),"Outer fully closed");t.assertTrue(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Actual clear subject admitted");t.assertTrue(i.base.filter().airlock().phase.equals("admitted"),"Live phase tracks admission");finish(t,p);});});}
    @GameTest(structure=S,maxTicks=120) public void restrictedVisitorReturnsOutsideWithoutOpeningInner(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);p.getInventory().setItem(2,new ItemStack(Items.TNT));start(t,i,p);t.runAfterDelay(15,()->{inside(i,p);t.runAfterDelay(35,()->{t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"TNT never opens inner");t.assertTrue(i.outer.getBlockState().getValue(SecurityDoorBlock.OPEN),"Outer allows retreat");t.assertTrue(i.base.filter().airlock().returning,"Turn rejected");finish(t,p);});});}
    @GameTest(structure=S,maxTicks=120) public void twoOccupantsInvalidateSinglePassAdmission(GameTestHelper t){var i=setup(t);enable(t,i);var a=visitor(t,i);var b=visitor(t,i);start(t,i,a);inside(i,a);b.setPos(a.position().add(.7,0,0));t.runAfterDelay(20,()->{t.assertTrue(i.base.filter().airlock().phase.equals("multiple"),"Tailgating detected");t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Both occupants returned instead of entering");finish(t,a,b);});}
    @GameTest(structure=S,maxTicks=120) public void revokedCredentialDuringEntryCannotOpenInner(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);start(t,i,p);AccessRegistry.get(t.getLevel()).revoke(p.getInventory().getItem(0).get(UmbralContent.CARD_ID),i.base.owner().getUUID(),i.base.core().link());inside(i,p);t.runAfterDelay(35,()->{t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Revoked pass fails fresh check");t.assertTrue(i.base.filter().airlock().returning,"Visitor can return");finish(t,p);});}
    @GameTest(structure=S,maxTicks=120) public void droppingPassDuringEntryCannotOpenInner(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);start(t,i,p);p.getInventory().clearContent();inside(i,p);t.runAfterDelay(35,()->{t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Pass must still be carried");finish(t,p);});}
    @GameTest(structure=S,maxTicks=160) public void returningVisitorLeavesAndTurnResets(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);p.getInventory().setItem(2,new ItemStack(Items.TNT));start(t,i,p);inside(i,p);t.runAfterDelay(35,()->{p.setPos(Vec3.atLowerCornerOf(i.outer.getBlockPos()).add(.5,0,-2));t.runAfterDelay(35,()->{t.assertTrue(i.base.filter().airlock().subject==null&&AirlockService.closed(t.getLevel(),i.outer),"Empty rejected turn closes and resets without reopening loop");finish(t,p);});});}
    @GameTest(structure=S) public void restartPersistsInterlockAndDiscardsAdmissionToken(GameTestHelper t){var i=setup(t);enable(t,i);i.base.filter().airlock().begin(UUID.randomUUID(),UUID.randomUUID(),false,0);var copy=new DeviceBlockEntity(i.base.filter().getBlockPos(),i.base.filter().getBlockState());copy.setLevel(t.getLevel());copy.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,t.getLevel().registryAccess(),i.base.filter().saveWithoutMetadata(t.getLevel().registryAccess())));t.assertTrue(copy.airlock().enabled()&&copy.airlock().outer().equals(i.outer.asDoorTarget()),"Configured layout survives reload");t.assertTrue(copy.airlock().subject==null,"Transient credentials never persisted");var door=new DeviceBlockEntity(i.outer.getBlockPos(),i.outer.getBlockState());door.setLevel(t.getLevel());door.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,t.getLevel().registryAccess(),i.outer.saveWithoutMetadata(t.getLevel().registryAccess())));t.assertTrue(door.airlockLink().equals(i.outer.airlockLink()),"Physical interlock survives reload");t.succeed();}
    @GameTest(structure=S) public void controllerLossBlocksAdmissionsAndOwnerCanRecover(GameTestHelper t){var i=setup(t);enable(t,i);t.setBlock(FilterGameTests.FILTER,Blocks.AIR);t.assertTrue(AirlockService.card(i.base.owner(),i.outer,UUID.randomUUID())==AccessService.Result.AIRLOCK_UNAVAILABLE,"Lost inspector blocks new entry");t.assertTrue(AirlockService.recover(i.base.owner(),i.outer),"Owner recovery after destroyed controller");t.assertTrue(i.outer.airlockLink()==null&&i.base.door().airlockLink()==null,"Recovery clears surviving pair");t.succeed();}
    @GameTest(structure=S) public void doorReplacementInvalidatesAdmissionIdentity(GameTestHelper t){var i=setup(t);enable(t,i);t.setBlock(OUT,Blocks.AIR);new FilterGameTests().put(t,OUT,UmbralContent.DOOR,i.base.owner());t.assertTrue(AirlockService.card(i.base.owner(),i.base.door(),UUID.randomUUID())==AccessService.Result.AIRLOCK_UNAVAILABLE,"Same-coordinate replacement cannot inherit controller trust");t.succeed();}
    @GameTest(structure=S,maxTicks=160) public void exitNeedsNoCardAndIgnoresIncomingItemRestriction(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);p.getInventory().clearContent();p.getInventory().setItem(2,new ItemStack(Items.TNT));p.setPos(Vec3.atLowerCornerOf(i.base.door().getBlockPos()).add(.5,0,1.5));t.assertTrue(AirlockService.manual(p,i.base.door()),"Base-side manual exit handled without card");t.runAfterDelay(15,()->{inside(i,p);t.runAfterDelay(35,()->{t.assertTrue(AirlockService.closed(t.getLevel(),i.base.door())&&i.outer.getBlockState().getValue(SecurityDoorBlock.OPEN),"Interior closes before uninspected exit opens outside");p.setPos(Vec3.atLowerCornerOf(i.outer.getBlockPos()).add(.5,0,-2));t.runAfterDelay(30,()->{t.assertTrue(i.base.filter().airlock().subject==null&&AirlockService.closed(t.getLevel(),i.outer),"Completed exit resets without reopening loop");finish(t,p);});});});}
    @GameTest(structure=S,maxTicks=120) public void outageStillAllowsManualRetreatWithoutNewAdmission(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);start(t,i,p);inside(i,p);t.setBlock(FilterGameTests.CORE,Blocks.AIR);NetworkService.invalidate(t.getLevel());t.runAfterDelay(25,()->{t.assertTrue(AirlockService.card(p,i.outer,p.getInventory().getItem(0).get(UmbralContent.CARD_ID))==AccessService.Result.AIRLOCK_UNAVAILABLE,"No new network admission");t.assertTrue(AirlockService.manual(p,i.outer),"Interior side can request escape offline");t.assertTrue(i.outer.getBlockState().getValue(SecurityDoorBlock.OPEN),"Escape opens surviving outside door");t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Inner remains closed");finish(t,p);});}
    @GameTest(structure=S,maxTicks=80) public void expiredAdmissionReturnsRatherThanUnlockingBase(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);start(t,i,p);inside(i,p);i.base.filter().airlock().deadline=t.getLevel().getGameTime()-1;t.runAfterDelay(20,()->{t.assertTrue(i.base.filter().airlock().returning&&i.base.filter().airlock().phase.equals("timeout"),"Expired turn returns");t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Timeout cannot admit");finish(t,p);});}
    @GameTest(structure=S) public void foreignRecoveryCannotRemoveDoorInterlocks(GameTestHelper t){var i=setup(t);enable(t,i);t.assertFalse(AirlockService.recover(i.base.visitor(),i.outer),"Only owner can recover");t.assertTrue(i.outer.airlockLink()!=null&&i.base.filter().airlock().enabled(),"Foreign recovery does not mutate");t.succeed();}
    @GameTest(structure=S) public void exteriorManualUseCannotBypassReader(GameTestHelper t){var i=setup(t);enable(t,i);var p=visitor(t,i);p.getInventory().clearContent();t.assertTrue(AirlockService.manual(p,i.outer),"Exterior use handled");t.assertFalse(i.outer.getBlockState().getValue(SecurityDoorBlock.OPEN),"Unauthenticated exterior cannot enter");finish(t,p);}

    @GameTest(structure=S,maxTicks=80) public void occupiedChamberCannotUseExitRequestToBypassInspection(GameTestHelper t){var i=setup(t);enable(t,i);var intruder=visitor(t,i);inside(i,intruder);var leaving=visitor(t,i);leaving.getInventory().clearContent();leaving.setPos(Vec3.atLowerCornerOf(i.base.door().getBlockPos()).add(.5,0,1.5));AirlockService.manual(leaving,i.base.door());t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Unidentified occupant cannot use someone else's exit to open base");t.runAfterDelay(20,()->{t.assertFalse(i.base.door().getBlockState().getValue(SecurityDoorBlock.OPEN),"Unsafe exit remains rejected");t.assertTrue(i.outer.getBlockState().getValue(SecurityDoorBlock.OPEN),"Existing occupant can retreat outside");finish(t,intruder,leaving);});}

}
